نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
LTIFR این ماه نسبت به ماه قبل 81٪ افزایش داشته. چه اتفاقی افتاده؟ (مدیر HSE — معدن سنگ‌آهن سنگان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ltifr"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "ltifr": {
    "prev_month": 1.4,
    "curr_month": 2.53,
    "change_pct": 81
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "safety_incidents",
    "filters": {
      "period": "this_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "incidents": [
    {
      "type": "سقوط از ارتفاع",
      "count": 2,
      "shift": "شیفت شب",
      "lost_days": 12
    },
    {
      "type": "برخورد تجهیزات",
      "count": 1,
      "shift": "شیفت صبح",
      "lost_days": 8
    }
  ],
  "total_lti": 3,
  "root_note": "دو مورد سقوط از ارتفاع در شیفت شب (ساعت ۲ تا ۵ صبح) با نور کم و خستگی"
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
برای کاهش انتشار گازهای گلخانه‌ای سه گزینه داریم. کدام به‌صرفه‌تر است؟ (مدیر HSE — معدن سنگ‌آهن سنگان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "emissions",
      "description": "انتشار گازهای گلخانه‌ای و آلاینده‌ها",
      "dimensions": [
        "source",
        "period"
      ],
      "measures": [
        "tons_co2",
        "kg_nox",
        "kg_so2"
      ]
    },
    {
      "dataset": "permits",
      "description": "مجوزها و انطباق با شرایط",
      "dimensions": [
        "permit_type",
        "authority"
      ],
      "measures": [
        "status",
        "expiry_date",
        "violations"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ghg_intensity",
      "description": "شدت انتشار گازهای گلخانه‌ای",
      "formula": "انتشار کل CO2e / تن محصول",
      "unit": "کیلوگرم CO2e بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ghg_intensity"
    ],
    "period": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "ghg_kg_per_ton": 177,
  "target_kg_per_ton": 91
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "permits",
    "filters": {
      "permit_type": "emissions"
    }
  }
}

TOOL_OBSERVATION:
{
  "options": [
    {
      "name": "فیلتر ساده",
      "cost_m_toman": 1102,
      "reduction_pct": 22
    },
    {
      "name": "سیستم بازیافت حرارتی",
      "cost_m_toman": 1649,
      "reduction_pct": 33
    },
    {
      "name": "تغییر سوخت + فیلتر پیشرفته",
      "cost_m_toman": 2296,
      "reduction_pct": 53
    }
  ]
}

