چند ماه است که انتشار ذرات معلق از حد مجاز مجوز بالاتر رفته. علت و هزینهٔ جریمه چقدر است؟ (مدیر HSE — مجتمع معدنی گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "permits",
      "description": "مجوزها و انطباق با شرایط",
      "dimensions": [
        "permit_type",
        "authority"
      ],
      "measures": [
        "status",
        "expiry_date",
        "violations"
      ]
    },
    {
      "dataset": "environmental_monitoring",
      "description": "پایش محیط زیست: انتشار، مصرف آب، پسماند",
      "dimensions": [
        "parameter",
        "station",
        "period"
      ],
      "measures": [
        "value",
        "limit",
        "unit"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ghg_intensity",
      "description": "شدت انتشار گازهای گلخانه‌ای",
      "formula": "انتشار کل CO2e / تن محصول",
      "unit": "کیلوگرم CO2e بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
