      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
